# generate grid per described tiled rule; print compact JSON
H=W=28
g=[[0]*W for _ in range(H)]
# separators
for r in [4,9,14,19,24]: g[r]=[8]*W
for c in [4,9,14,19,24]:
 for r in range(H): g[r][c]=8
# 2 row-band block row1 cols0..4; plus vertical block col0 rows1..3
for br in range(1,4):
 for bc in range(5):
  if br==1 or bc==0:
   for r in range(br*5,br*5+4):
    for c in range(bc*5,bc*5+4): g[r][c]=2
# 3 vertical block col2 rows0..4, overrides intersection
for br in range(5):
 for r in range(br*5,br*5+4):
  for c in range(10,14): g[r][c]=3
# print output
import json
print(json.dumps(g,separators=(',',':')))
